using namespace std;
stack<int>/*或其他类型名*/ S1, S2;
int x;/*或其他类型名*/ 
/*元素x入队：*/
void Queue_push(int x)
{
    S1.push(x);
}

/*队头元素出队：*/
void Queue_pop()
{
    while(!S1.empty())
    {
        S2.push(S1.top());
        S1.pop();
    }
    if(S2.empty())
    {
        cerr<<"This queue is empty!"<<endl;
        return;
    }
    S2.pop();
    while(!S2.empty())
    {
        S1.push(S2.top());
        S2.pop();
    }
}        

/*判断队列是否为空*/
bool Queue_empty()
{
    if(S1.empty())return true;
    else return false;
}

