answer:
利用两个栈s1和s2来模拟一个队列，当需要向队列中插入一个元素时
用S1来存放已输入的元素，即S1执行入队操作。当需要出队时，则队S2执行
出栈操作。必须先将S1中所有元素出栈并入栈到S2中，再在S2中出栈
即可实现出队操作，而在执行此操作之前必须判断S2是否为空，否则导致顺序混乱
当栈S1和S2都为空时队列为空。
即：
①对S2的出栈操作用作出队，若S2为空则先将S1中所有元素送入S2
②对S1的入栈操作用作入队，若S1满，必须先保证S2为空，才能将S1中
的元素全部插入S2中




（1）出队算法



int EnQ(Stack &S1,Stack &S2,Elemtype e){
    if(!StackOverflow(S1)){
        Push(S1,e);
        return 1;
    }
    if(StackOverflow(S1)&&!StackEmpty(S2)){
        printf("队列满");
        return 0;
    }
    if(StackOverflow(S1)&&StackEmpty(S2)){
        while(!StackEmpty(S1)){
            Pop(S1,x);
            Push(S2,x);
        }
        Push(S1,e);
        return 1;
    }
} 




（2）入队算法



void DeQueue(Stack &S1,Stack &S2,Elemtype &x){
    if(!StackEmpty(S2)){
        Pop(S2,x); 
    }
    else if(!StackEmpty(S1)){
        printf("队列为空");
    }
    else{
        while(!StackEmpty(S1)){
        Pop(S1,x);
        Push(S2,x); 
    }
    Pop(S2,x);
}
} 




（3）判断队列为空算法



int QueueEmpty(Stack S1,Stack S2){
    if(StackEmpty(S1)&&StackEmpty(S2)){
        return 1;
    }
    else return 0;
}

